// Test bench for exhaustive simulationmodule t_Sequential_Binary_Multiplier;  parameter					dp_width = 5;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire							Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;    Sequential_Binary_Multiplier M0 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #109200 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  initial begin #5 Start = 1; end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;    repeat (31) #10 begin Multiplier = Multiplier + 1;      repeat (32) @ (posedge M0.Ready) #5 Multiplicand = Multiplicand + 1;    end    Start = 0;  end// Error Checker  reg Error;  reg [2*dp_width -1: 0] Exp_Value;  always @ (posedge Ready) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand + 1;	     // Inject error to verify detection    Error = (Exp_Value ^ Product);  end  wire [2: 0] state = {M0.M0.G2, M0.M0.G1, M0.M0.G0};	// Watch stateendmodule  module Sequential_Binary_Multiplier    #(parameter dp_width =	5) (  output [2*dp_width -1: 0]  	Product,  output 						Ready,   input [dp_width -1: 0] 		Multiplicand, Multiplier,   input 						Start, clock, reset_b);	   wire Load_regs, Decr_P, Add_regs, Shift_regs, Zero, Q0;  Controller M0 (Ready, Load_regs, Decr_P, Add_regs, Shift_regs, Start, Zero, Q0, clock, reset_b);  Datapath M1(Product, Q0, Zero,Multiplicand, Multiplier, Start, Load_regs, Decr_P, Add_regs,     Shift_regs, clock, reset_b);	endmodulemodule Controller (  output Ready,  output Load_regs, Decr_P, Add_regs, Shift_regs,     input Start, Zero, Q0, clock, reset_b);// One-Hot Control unit (See Fig. 8.18)	  wire G0, G1, G2, D0, w1, w2, D1, w3, w4;  DFF_S M0 (G0, D0, clock, Set);  DFF M1 (G1, D1, clock, reset_b);  DFF M2 (G2, G1, clock, reset_b);  or (D0, w1, w2);  and (w1, G0, Start_b);  and (w2, Zero, G2);  not (Start_b, Start);  not (Zero_b, Zero);  or (D1, w3, w4);  and (w3, Start, G0);  and (w4, Zero_b, G2);    and (Load_regs, G0, Start);  and (Add_regs, Q0, G1);  assign Ready = G0;    assign Decr_P = G1;  assign Shift_regs = G2;  not (Set, reset_b);endmodule
module Datapath #(parameter dp_width = 5, BC_size = 3) (  output [2*dp_width - 1: 0] Product, output Q0, output Zero,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);  reg	[dp_width - 1: 0]		A, B, Q;			// Sized for datapath  reg 				C;  reg	[BC_size - 1: 0]		P;  assign				Product = {C, A, Q};  // Status signals  assign				Zero = (P == 0);		// counter is zero  assign				Q0 = Q[0];  always @ (posedge clock) begin    if (Load_regs) begin      P <= dp_width;      A <= 0;      C <= 0;      B <= Multiplicand;      Q <= Multiplier;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Decr_P) P <= P -1;  endendmodule module DFF_S (output reg Q, input data, clock, Set);  always @ ( posedge clock, posedge Set)    if (Set) Q <= 1'b1; else Q<= data;endmodulemodule DFF (output reg Q, input data, clock, reset_b);  always @ ( posedge clock, negedge reset_b)    if (reset_b == 0) Q <= 1'b0; else Q<= data;endmodule